<?php
class ActivityService
{
    private $pdo;
    private $defaults = array(
        'lottery' => array('name'=>'幸运抽奖','description'=>'每日一次抽奖，中奖后获得站内抵扣券。','config'=>array('daily_limit'=>1,'win_weight'=>10)),
        'referral' => array('name'=>'拉人返佣','description'=>'邀请好友首笔有效付款返佣自动入消费余额，历史佣金提现仍由管理员人工审核。','config'=>array('rate_bps'=>1000,'minimum_withdraw_cents'=>5000)),
        'group' => array('name'=>'好友拼单','description'=>'三人成团后享受活动折扣，拼团有效期 24 小时。','config'=>array('target_members'=>3,'discount_percent'=>80,'duration_hours'=>24)),
        'leader' => array('name'=>'团长免单','description'=>'成功邀请 3 名不同用户完成有效付款后，领取一次指定套餐免单权益。','config'=>array('required_referrals'=>3,'reward_plan_id'=>0)),
    );
    public function __construct($pdo){$this->pdo=$pdo;}
    public function defaults($key){return isset($this->defaults[$key])?$this->defaults[$key]:array('name'=>$key,'description'=>'','config'=>array());}
    public function setting($key,$lock=false){
        $sql='SELECT * FROM activity_settings WHERE activity_key=?'.($lock?' FOR UPDATE':'');
        try{$s=$this->pdo->prepare($sql);$s->execute(array($key));$row=$s->fetch();}catch(Exception $e){return null;}
        if($row)return $row;
        $d=$this->defaults($key);$now=date('Y-m-d H:i:s');
        try{$this->pdo->prepare('INSERT INTO activity_settings(activity_key,name,description,status,config_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?)')->execute(array($key,$d['name'],$d['description'],'disabled',json_encode($d['config'],JSON_UNESCAPED_UNICODE),$now,$now));$s=$this->pdo->prepare('SELECT * FROM activity_settings WHERE activity_key=?'.($lock?' FOR UPDATE':''));$s->execute(array($key));return $s->fetch();}catch(Exception $e){return null;}
    }
    public function config($key){$row=$this->setting($key);$base=$this->defaults($key)['config'];$saved=$row&&$row['config_json']?json_decode($row['config_json'],true):array();return array_merge($base,is_array($saved)?$saved:array());}
    public function enabled($key){$row=$this->setting($key);if(!$row||$row['status']!=='enabled')return false;$now=time();return (!$row['start_at']||strtotime($row['start_at'])<=$now)&&(!$row['end_at']||strtotime($row['end_at'])>=$now);}
    public function saveSetting($key,$input,$adminId){$d=$this->defaults($key);$config=array_merge($d['config'],is_array($input['config'])?$input['config']:array());$this->validateMarketingConfig($key,$config);$status=in_array($input['status'],array('enabled','disabled'),true)?$input['status']:'disabled';$name=trim(isset($input['name'])?$input['name']:$d['name']);$description=trim(isset($input['description'])?$input['description']:$d['description']);$start=isset($input['start_at'])&&$input['start_at']!==''?$input['start_at']:null;$end=isset($input['end_at'])&&$input['end_at']!==''?$input['end_at']:null;$now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO activity_settings(activity_key,name,description,status,config_json,start_at,end_at,created_by,updated_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),status=VALUES(status),config_json=VALUES(config_json),start_at=VALUES(start_at),end_at=VALUES(end_at),updated_by=VALUES(updated_by),updated_at=VALUES(updated_at)')->execute(array($key,$name,$description,$status,json_encode($config,JSON_UNESCAPED_UNICODE),$start,$end,$adminId,$adminId,$now,$now));return $this->setting($key);}
    // Marketing eligibility is explicit; never infer an order's type from today's product.
    private function assertVpnPlan($planId){$s=$this->pdo->prepare('SELECT pp.id FROM product_plans pp JOIN products p ON p.id=pp.product_id WHERE pp.id=? AND p.product_type="vpn"');$s->execute(array((int)$planId));if(!$s->fetch())throw new InvalidArgumentException('账号商品或无效方案不能参加营销活动。');}
    private function validateMarketingConfig($key,$config){if($key==='group')foreach((array)(isset($config['plan_ids'])?$config['plan_ids']:array()) as $id)$this->assertVpnPlan($id);if($key==='leader'&&!empty($config['reward_plan_id']))$this->assertVpnPlan($config['reward_plan_id']);}
    // Keep unlinked legacy commissions eligible; linked orders must have a VPN snapshot.
    private function eligibleCommissionSql(){return '(NOT EXISTS (SELECT 1 FROM orders mo WHERE mo.id=referral_commissions.order_id) OR EXISTS (SELECT 1 FROM orders mo WHERE mo.id=referral_commissions.order_id AND mo.product_type_snapshot="vpn"))';}
    private function code($prefix){return strtoupper($prefix.date('ymdHis').substr(strtoupper(bin2hex(random_bytes(8))),0,8));}
    private function notify($uid,$type,$title,$content,$eventKey=null){(new NotificationService($this->pdo))->create($uid,$type,$title,$content,null,null,null,$eventKey);}
    public function referralCode($userId){$s=$this->pdo->prepare('SELECT referral_code FROM users WHERE id=? AND status="active"');$s->execute(array((int)$userId));$code=(string)$s->fetchColumn();if($code!=='')return $code;$code='R'.strtoupper(substr(bin2hex(random_bytes(10)),0,20));$this->pdo->prepare('UPDATE users SET referral_code=? WHERE id=? AND (referral_code IS NULL OR referral_code="")')->execute(array($code,(int)$userId));$s=$this->pdo->prepare('SELECT referral_code FROM users WHERE id=?');$s->execute(array((int)$userId));return (string)$s->fetchColumn();}
    public function referrerByCode($code){$code=strtoupper(trim($code));if(preg_match('/^R[0-9A-F]{20}$/',$code)){$s=$this->pdo->prepare('SELECT id FROM users WHERE referral_code=? AND status="active"');$s->execute(array($code));$id=(int)$s->fetchColumn();if($id)return $id;}if(!preg_match('/^R[0-9A-Z]+$/',$code))return 0;$legacy=base_convert(substr($code,1),36,10);if(!ctype_digit((string)$legacy))return 0;$s=$this->pdo->prepare('SELECT id FROM users WHERE id=? AND status="active"');$s->execute(array((int)$legacy));return (int)$s->fetchColumn();}
    public function bindReferral($userId,$code){$ref=$this->referrerByCode($code);if(!$ref||$ref===$userId)return false;$s=$this->pdo->prepare('SELECT id FROM referral_relations WHERE user_id=?');$s->execute(array($userId));if($s->fetch())return false;$now=date('Y-m-d H:i:s');try{$this->pdo->prepare('INSERT INTO referral_relations(user_id,referrer_user_id,status,source,created_at,updated_at) VALUES(?,?,"active","register",?,?)')->execute(array($userId,$ref,$now,$now));return true;}catch(Exception $e){return false;}}
    public function lottery($userId){
        if(!$this->enabled('lottery'))throw new RuntimeException('幸运抽奖当前未开启。');$cfg=$this->config('lottery');$today=date('Y-m-d');$this->pdo->beginTransaction();try{$lock=$this->pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$lock->execute(array($userId));if(!$lock->fetch())throw new RuntimeException('用户不存在。');$a=$this->setting('lottery',true);$s=$this->pdo->prepare('SELECT COUNT(*) FROM lottery_draws WHERE activity_id=? AND user_id=? AND created_at>=? AND created_at<? FOR UPDATE');$s->execute(array($a['id'],$userId,$today.' 00:00:00',date('Y-m-d',strtotime('+1 day')).' 00:00:00'));if((int)$s->fetchColumn()>=$cfg['daily_limit'])throw new RuntimeException('今天的抽奖次数已用完。');$ps=$this->pdo->prepare('SELECT * FROM lottery_prizes WHERE activity_id=? AND status="active" AND weight>0 AND (remaining_quantity<0 OR remaining_quantity>0) ORDER BY sort_order,id FOR UPDATE');$ps->execute(array($a['id']));$prizes=$ps->fetchAll();if(!$prizes)throw new RuntimeException('当前奖池暂无可用奖品，请稍后再试。');$winner=null;$total=0;foreach($prizes as $p)$total+=(int)$p['weight'];$roll=random_int(1,10000);$cursor=0;$winWeight=max(0,min(100,(int)$cfg['win_weight']));if($total>0&&$roll<=$winWeight*100){$pick=random_int(1,$total);foreach($prizes as $p){$cursor+=(int)$p['weight'];if($pick<=$cursor){$winner=$p;break;}}}$drawNo=$this->code('D');$requestKey=(int)$cfg['daily_limit']===1?'lottery:'.$a['id'].':'.$userId.':'.$today:null;$this->pdo->prepare('INSERT INTO lottery_draws(draw_no,request_key,activity_id,user_id,prize_id,status,result_code,result_payload,created_at,completed_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute(array($drawNo,$requestKey,$a['id'],$userId,$winner?$winner['id']:null,$winner?'won':'no_prize',$winner?$winner['prize_code']:'',json_encode($winner?$winner:array('name'=>'谢谢参与'),JSON_UNESCAPED_UNICODE),date('Y-m-d H:i:s'),date('Y-m-d H:i:s')));if(!$winner){$this->notify($userId,'lottery','抽奖结果','本次抽奖未中奖，明天还可以继续参与。','lottery_draw:'.$drawNo);$this->pdo->commit();return array('won'=>false,'message'=>'谢谢参与，明天再来试试。');}$coupon=$this->issueCoupon($userId,$a['id'],$winner['name'],(int)$winner['value_cents'],0,(int)$winner['valid_days'],(int)$winner['min_amount_cents']);if((int)$winner['remaining_quantity']>=0){$stock=$this->pdo->prepare('UPDATE lottery_prizes SET remaining_quantity=remaining_quantity-1,updated_at=? WHERE id=? AND status="active" AND remaining_quantity>0');$stock->execute(array(date('Y-m-d H:i:s'),$winner['id']));if($stock->rowCount()!==1)throw new RuntimeException('奖品库存刚刚耗尽，请重新抽奖。');}$this->notify($userId,'lottery','恭喜中奖','你获得了「'.$winner['name'].'」，优惠券 '.$coupon['code'].' 已发放。','lottery_draw:'.$drawNo);$this->pdo->commit();return array('won'=>true,'prize'=>$winner['name'],'coupon'=>$coupon['code']);}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function issueCoupon($userId,$activityId,$name,$amountCents,$percent=0,$days=30,$minCents=0,$planId=0){if((int)$planId!==0)$this->assertVpnPlan($planId);$now=date('Y-m-d H:i:s');$code=$this->code('CP');$expires=date('Y-m-d H:i:s',strtotime('+'.max(1,(int)$days).' days'));$this->pdo->prepare('INSERT INTO coupons(activity_id,scope,user_id,code,name,coupon_type,amount_cents,discount_percent,max_discount_cents,min_amount_cents,product_plan_id,total_quantity,used_quantity,per_user_limit,status,starts_at,expires_at,created_at,updated_at) VALUES(?,"personal",?,?,?,?,?,?,?,?,?,1,0,1,"active",?,?,?,?)')->execute(array($activityId,$userId,$code,$name,$percent?'percent':'fixed',$amountCents,$percent,0,$minCents,$planId,$now,$expires,$now,$now));return array('id'=>$this->pdo->lastInsertId(),'code'=>$code);}
    public function userCoupons($userId){try{$s=$this->pdo->prepare('SELECT * FROM coupons WHERE user_id=? ORDER BY id DESC');$s->execute(array($userId));return $s->fetchAll();}catch(Exception $e){return array();}}
    public function prepareCoupon($userId,$code,$planId,$amount){$code=trim((string)$code);$amount=(int)$amount;$this->assertVpnPlan($planId);if($code==='')return array('discount'=>0);if(!$this->pdo->inTransaction())throw new LogicException('优惠校验必须在订单事务内执行。');if($amount<0)throw new InvalidArgumentException('订单金额无效。');$s=$this->pdo->prepare('SELECT * FROM coupons WHERE code=? AND (scope="public" OR (scope="personal" AND user_id=?)) AND status="active" FOR UPDATE');$s->execute(array($code,(int)$userId));$c=$s->fetch();if(!$c)throw new RuntimeException('优惠券不存在或已失效。');if($c['scope']==='personal'&&((int)$c['used_quantity']>0||!empty($c['used_order_id'])))throw new RuntimeException('该个人券已被占用。');$now=time();if(($c['starts_at']&&strtotime($c['starts_at'])>$now)||($c['expires_at']&&strtotime($c['expires_at'])<$now))throw new RuntimeException('优惠券已过期或尚未生效。');if((int)$c['total_quantity']>=0&&(int)$c['used_quantity'] >= (int)$c['total_quantity'])throw new RuntimeException('优惠券已领用完。');if((int)$c['min_amount_cents']>$amount)throw new RuntimeException('订单金额未达到优惠券使用门槛。');if(!empty($c['product_plan_id'])&&(int)$c['product_plan_id']!==(int)$planId)throw new RuntimeException('该优惠券不适用于当前方案。');$used=$this->pdo->prepare('SELECT id FROM order_promotions WHERE coupon_id=? AND user_id=? AND status="applied" FOR UPDATE');$used->execute(array((int)$c['id'],(int)$userId));if(count($used->fetchAll())>=(int)$c['per_user_limit'])throw new RuntimeException('你已达到该优惠券的使用次数上限。');$percent=max(0,min(100,(int)$c['discount_percent']));$discount=$c['coupon_type']==='percent'?(intdiv($amount,100)*$percent+intdiv(($amount%100)*$percent,100)):(int)$c['amount_cents'];if((int)$c['max_discount_cents']>0)$discount=min($discount,(int)$c['max_discount_cents']);$discount=min($amount,max(0,$discount));return array('discount'=>$discount,'coupon'=>$c);}
    public function applyPromotion($orderId,$promotion,$code){
        if(empty($promotion['coupon']))return;
        if(!$this->pdo->inTransaction())throw new LogicException('优惠占用必须在订单事务内执行。');
        $s=$this->pdo->prepare('SELECT * FROM orders WHERE id=? FOR UPDATE');$s->execute(array($orderId));$order=$s->fetch();if(!$order)throw new RuntimeException('订单不存在。');if($order['product_type_snapshot']!=='vpn')throw new RuntimeException('账号订单不能使用优惠券。');
        $existing=$this->pdo->prepare('SELECT * FROM order_promotions WHERE order_id=? AND promotion_key="coupon"');$existing->execute(array($orderId));$row=$existing->fetch();if($row){if($row['status']==='applied'&&(int)$row['coupon_id']===(int)$promotion['coupon']['id'])return;throw new RuntimeException('订单已有优惠记录。');}
        $fresh=$this->prepareCoupon($order['user_id'],$code,$order['product_plan_id'],$order['original_amount_cents']);$c=$fresh['coupon'];if((int)$c['id']!==(int)$promotion['coupon']['id']||(int)$fresh['discount']!==(int)$promotion['discount'])throw new RuntimeException('优惠配置已变化，请重新下单。');
        $now=date('Y-m-d H:i:s');$this->pdo->prepare('UPDATE coupons SET status=IF(scope="personal","used",status),used_quantity=used_quantity+1,used_order_id=IF(scope="personal",?,used_order_id),updated_at=? WHERE id=? AND status="active"')->execute(array($orderId,$now,$c['id']));
        $this->pdo->prepare('INSERT INTO order_promotions(order_id,user_id,promotion_key,promotion_type,promotion_id,promotion_code,coupon_id,discount_amount_cents,idempotency_key,created_at,updated_at) VALUES(?,?,"coupon","coupon",?,?,?,?,?,?,?)')->execute(array($orderId,$order['user_id'],$c['id'],$c['code'],$c['id'],$fresh['discount'],'coupon:'.$orderId,$now,$now));
    }
    // Caller owns the transaction and locks the order before any coupon rows.
    public function releaseCoupon($orderId){
        if(!$this->pdo->inTransaction())throw new LogicException('优惠释放必须在订单事务内执行。');
        $s=$this->pdo->prepare('SELECT id FROM orders WHERE id=? FOR UPDATE');$s->execute(array($orderId));if(!$s->fetch())return;
        $s=$this->pdo->prepare('SELECT DISTINCT coupon_id FROM order_promotions WHERE order_id=? AND coupon_id IS NOT NULL ORDER BY coupon_id');$s->execute(array($orderId));$ids=$s->fetchAll(PDO::FETCH_COLUMN);
        foreach($ids as $id){$s=$this->pdo->prepare('SELECT * FROM coupons WHERE id=? FOR UPDATE');$s->execute(array($id));$c=$s->fetch();if(!$c)continue;$now=date('Y-m-d H:i:s');$s=$this->pdo->prepare('UPDATE order_promotions SET status="reversed",updated_at=? WHERE order_id=? AND coupon_id=? AND status="applied"');$s->execute(array($now,$orderId,$id));$count=$s->rowCount();if(!$count)continue;
            $this->pdo->prepare('UPDATE coupons SET used_quantity=GREATEST(used_quantity-?,0),status=IF(scope="personal" AND status="used" AND used_order_id=?,"active",status),used_order_id=IF(scope="personal" AND used_order_id=?,NULL,used_order_id),updated_at=? WHERE id=?')->execute(array($count,$orderId,$orderId,$now,$id));
        }
    }
    // 调用方持有订单事务，并已按用户 ID 升序锁定所有结算用户。
    public function settlePaidOrder($orderId){
        if(!$this->pdo->inTransaction())throw new LogicException('返佣结算必须在订单事务内执行。');
        $o=$this->pdo->prepare('SELECT * FROM orders WHERE id=? FOR UPDATE');$o->execute(array($orderId));$order=$o->fetch();
        if(!$order||$order['product_type_snapshot']!=='vpn'||!in_array($order['status'],array('pending_delivery','delivered'),true)||empty($order['paid_at']))return;
        // 已存在的订单佣金（包括已撤销和历史记录）不得再次发放。
        $s=$this->pdo->prepare('SELECT id FROM referral_commissions WHERE order_id=? LIMIT 1 FOR UPDATE');$s->execute(array($orderId));if($s->fetch())return;
        $s=$this->pdo->prepare('SELECT * FROM referral_relations WHERE user_id=? AND status="active" FOR UPDATE');$s->execute(array($order['user_id']));$rel=$s->fetch();
        if($rel&&$this->enabled('referral')){
            $cfg=$this->config('referral');$existing=$this->pdo->prepare('SELECT id FROM referral_commissions WHERE referred_user_id=? AND status IN ("available","approved","paid","pending_credit","credited") AND '.$this->eligibleCommissionSql().' ORDER BY id LIMIT 1 FOR UPDATE');$existing->execute(array($order['user_id']));
            if(!$existing->fetch()){
                $rate=max(0,min(10000,(int)$cfg['rate_bps']));$paid=(int)$order['total_amount_cents'];$amount=intdiv($paid,10000)*$rate+intdiv(($paid%10000)*$rate,10000);
                if($amount>0){
                    $now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO referral_commissions(commission_no,idempotency_key,relation_id,referrer_user_id,referred_user_id,order_id,amount_cents,rate_bps,settlement_mode,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,"wallet","pending_credit",?,?)')->execute(array($this->code('CM'),'commission:'.$orderId,$rel['id'],$rel['referrer_user_id'],$order['user_id'],$orderId,$amount,$rate,$now,$now));
                    $s=$this->pdo->prepare('SELECT * FROM referral_commissions WHERE id=? FOR UPDATE');$s->execute(array($this->pdo->lastInsertId()));$commission=$s->fetch();
                    if(!$this->creditCommission($commission))$this->notify($rel['referrer_user_id'],'referral_commission','邀请返佣待入账','好友已付款，返佣 ¥'.number_format($amount/100,2).' 因余额容量不足暂待入账。','commission:'.$commission['id'].':pending_credit');
                }
            }
        }
        $this->tryLeaderReward($rel?$rel['referrer_user_id']:0);
    }
    private function creditCommission($commission){
        $result=(new WalletService($this->pdo))->creditReferralCommission($commission);
        if($result['status']==='pending_credit')return false;
        if($result['status']!=='credited')throw new LogicException('返佣入账结果无效。');
        $now=date('Y-m-d H:i:s');$this->pdo->prepare('UPDATE referral_commissions SET status="credited",credited_at=?,updated_at=? WHERE id=? AND settlement_mode="wallet" AND status="pending_credit"')->execute(array($now,$now,$commission['id']));
        $this->notify($commission['referrer_user_id'],'referral_commission','邀请返佣到账','好友订单返佣 ¥'.number_format($commission['amount_cents']/100,2).' 已入消费余额。','commission:'.$commission['id'].':credited');return true;
    }
    private function recoverCommission($commission){
        $result=(new WalletService($this->pdo))->reverseReferralCommission($commission);
        if(!in_array($result['status'],array('recovered','pending_recovery'),true))throw new LogicException('返佣追回结果无效。');
        $recovered=$result['status']==='recovered';$now=date('Y-m-d H:i:s');
        $this->pdo->prepare('UPDATE referral_commissions SET status="reversed",recovery_status=?,recovered_at=?,updated_at=? WHERE id=?')->execute(array($recovered?'recovered':'pending',$recovered?$now:null,$now,$commission['id']));
        if($recovered||$commission['recovery_status']!=='pending')$this->notify($commission['referrer_user_id'],'referral_reversal',$recovered?'邀请返佣已撤回':'邀请返佣待追回',$recovered?'好友订单退款，已从消费余额扣回返佣 ¥'.number_format($commission['amount_cents']/100,2).'。':'好友订单退款，余额不足，原返佣 ¥'.number_format($commission['amount_cents']/100,2).' 整笔待追回。','commission:'.$commission['id'].':'.($recovered?'recovered':'pending_recovery'));
        return $recovered;
    }
    private function tryLeaderReward($userId){if(!$userId||!$this->enabled('leader'))return;$userLock=$this->pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$userLock->execute(array($userId));if(!$userLock->fetch())return;$cfg=$this->config('leader');$need=max(1,(int)$cfg['required_referrals']);$s=$this->pdo->prepare('SELECT COUNT(DISTINCT referred_user_id) FROM referral_commissions WHERE referrer_user_id=? AND status IN ("available","approved","paid","pending_credit","credited") AND '.$this->eligibleCommissionSql());$s->execute(array($userId));if((int)$s->fetchColumn()<$need||empty($cfg['reward_plan_id']))return;$a=$this->setting('leader');$s=$this->pdo->prepare('SELECT id FROM leader_rewards WHERE campaign_id=? AND leader_user_id=? FOR UPDATE');$s->execute(array($a['id'],$userId));if($s->fetch())return;$s=$this->pdo->prepare('SELECT pp.price_cents,pp.name FROM product_plans pp JOIN products p ON p.id=pp.product_id WHERE pp.id=? AND pp.status="active" AND p.product_type="vpn"');$s->execute(array((int)$cfg['reward_plan_id']));$plan=$s->fetch();if(!$plan)return;$coupon=$this->issueCoupon($userId,$a['id'],'团长免单券',(int)$plan['price_cents'],0,30,0,(int)$cfg['reward_plan_id']);$this->pdo->prepare('INSERT INTO leader_rewards(campaign_id,leader_user_id,coupon_id,reward_cents,status,awarded_at,created_at,updated_at) VALUES(?,?,?, ?,"awarded",?,?,?)')->execute(array($a['id'],$userId,$coupon['id'],$plan['price_cents'],date('Y-m-d H:i:s'),date('Y-m-d H:i:s'),date('Y-m-d H:i:s')));$this->notify($userId,'leader_reward','团长免单已达成','你已邀请 '.$need.' 名好友完成付款，团长免单券已发放。','leader_reward:'.$a['id'].':'.$userId);}
    public function requestWithdrawal($userId,$amountCents,$channel,$accountName,$accountNo){$cfg=$this->config('referral');$amount=(int)$amountCents;if($amount<(int)$cfg['minimum_withdraw_cents'])throw new InvalidArgumentException('提现金额未达到最低提现金额。');$channel=trim((string)$channel);$accountName=substr(trim((string)$accountName),0,120);$accountNo=substr(trim((string)$accountNo),0,190);if($channel===''||$accountNo==='')throw new InvalidArgumentException('请填写完整的收款信息。');$this->pdo->beginTransaction();try{$lock=$this->pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$lock->execute(array($userId));if(!$lock->fetch())throw new RuntimeException('用户不存在。');$s=$this->pdo->prepare('SELECT COALESCE(SUM(CASE WHEN status IN ("available","approved") THEN amount_cents ELSE 0 END),0)-COALESCE((SELECT SUM(amount_cents) FROM withdrawal_requests WHERE user_id=? AND status IN ("pending","approved","paid")),0) FROM referral_commissions WHERE referrer_user_id=? AND settlement_mode="legacy" FOR UPDATE');$s->execute(array($userId,$userId));if((int)$s->fetchColumn()<$amount)throw new RuntimeException('可提现佣金余额不足。');$now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO withdrawal_requests(request_no,user_id,amount_cents,net_amount_cents,channel,account_name,account_no,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,"pending",?,?)')->execute(array($this->code('WD'),$userId,$amount,$amount,$channel,$accountName,$accountNo,$now,$now));$id=$this->pdo->lastInsertId();$this->pdo->commit();return $id;}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function processWithdrawal($id,$adminId,$status,$reason){if(!in_array($status,array('approved','rejected','paid'),true))throw new InvalidArgumentException('提现状态无效。');$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT * FROM withdrawal_requests WHERE id=? FOR UPDATE');$s->execute(array((int)$id));$w=$s->fetch();if(!$w)throw new RuntimeException('提现申请不存在。');$allowed=($w['status']==='pending'&&in_array($status,array('approved','rejected'),true))||($w['status']==='approved'&&$status==='paid');if(!$allowed)throw new RuntimeException('提现状态不能从 '.$w['status'].' 变更为 '.$status.'。');$now=date('Y-m-d H:i:s');$this->pdo->prepare('UPDATE withdrawal_requests SET status=?,reviewed_by=?,reviewed_at=?,paid_at=IF(?="paid",?,paid_at),reject_reason=?,updated_at=? WHERE id=?')->execute(array($status,$adminId,$now,$status,$status==='paid'?$now:null,substr($reason,0,500),$now,$id));$this->notify($w['user_id'],'withdrawal_'.$status,'提现申请已更新','你的提现申请 '.$w['request_no'].' 状态为：'.$status.'。','withdrawal:'.$id.':'.$status);$this->pdo->prepare('INSERT INTO admin_logs(admin_id,action,target_type,target_id,details_json,created_at) VALUES(?,?,?,?,?,?)')->execute(array($adminId,'process_withdrawal','withdrawal',$id,json_encode(array('status'=>$status,'reason'=>substr($reason,0,500)),JSON_UNESCAPED_UNICODE),$now));$this->pdo->commit();}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function reverseOrder($orderId){
        if(!$this->pdo->inTransaction())throw new LogicException('返佣撤销必须在订单事务内执行。');
        $s=$this->pdo->prepare('SELECT * FROM referral_commissions WHERE order_id=? ORDER BY id FOR UPDATE');$s->execute(array($orderId));
        foreach($s->fetchAll() as $commission){
            if($commission['status']==='reversed')continue;
            if($commission['settlement_mode']==='wallet'&&$commission['status']==='credited'){$this->recoverCommission($commission);continue;}
            if(in_array($commission['status'],array('available','approved','paid','pending_credit'),true))$this->pdo->prepare('UPDATE referral_commissions SET status="reversed",updated_at=? WHERE id=?')->execute(array(date('Y-m-d H:i:s'),$commission['id']));
        }
    }
    public function processCommission($id,$adminId,$action){
        if(!in_array($action,array('credit','recover'),true)||(int)$id<=0||(int)$adminId<=0)throw new InvalidArgumentException('返佣处理参数无效。');
        if($this->pdo->inTransaction())throw new LogicException('返佣后台处理不能嵌套事务。');
        $this->pdo->beginTransaction();try{
            // 先读取不可变的订单 ID，避免在订单及用户之前锁定佣金。
            $s=$this->pdo->prepare('SELECT order_id FROM referral_commissions WHERE id=?');$s->execute(array((int)$id));$orderId=$s->fetchColumn();if(!$orderId)throw new RuntimeException('佣金记录不存在。');
            $s=$this->pdo->prepare('SELECT * FROM orders WHERE id=? FOR UPDATE');$s->execute(array($orderId));$order=$s->fetch();if(!$order)throw new RuntimeException('原订单不存在。');
            $ids=array((int)$order['user_id']);$s=$this->pdo->prepare('SELECT referrer_user_id FROM referral_relations WHERE user_id=? AND status="active"');$s->execute(array($order['user_id']));foreach($s->fetchAll(PDO::FETCH_COLUMN) as $uid)$ids[]=(int)$uid;
            $s=$this->pdo->prepare('SELECT referrer_user_id FROM referral_commissions WHERE order_id=?');$s->execute(array($orderId));foreach($s->fetchAll(PDO::FETCH_COLUMN) as $uid)$ids[]=(int)$uid;
            $ids=array_unique($ids);sort($ids,SORT_NUMERIC);$lock=$this->pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');foreach($ids as $uid){$lock->execute(array($uid));if(!$lock->fetch())throw new RuntimeException('结算用户不存在。');}
            $s=$this->pdo->prepare('SELECT * FROM referral_commissions WHERE id=? FOR UPDATE');$s->execute(array((int)$id));$commission=$s->fetch();if(!$commission||(int)$commission['order_id']!==(int)$orderId||$commission['settlement_mode']!=='wallet')throw new RuntimeException('仅可处理钱包佣金。');
            $before=$commission['status'];$recoveryBefore=$commission['recovery_status'];
            if($action==='credit'){
                if($order['product_type_snapshot']!=='vpn')throw new RuntimeException('账号订单不能新增返佣入账。');
                if($commission['status']==='credited')$success=true;
                elseif($commission['status']==='pending_credit'&&in_array($order['status'],array('pending_delivery','delivered','refunding'),true)&&!empty($order['paid_at']))$success=$this->creditCommission($commission);
                else throw new RuntimeException('该佣金不处于待入账状态。');
            }else{
                if($commission['status']!=='reversed')throw new RuntimeException('该佣金尚未撤销。');
                if($commission['recovery_status']==='recovered')$success=true;
                elseif($commission['recovery_status']==='pending')$success=$this->recoverCommission($commission);
                else throw new RuntimeException('该佣金不处于待追回状态。');
            }
            $this->pdo->prepare('INSERT INTO admin_logs(admin_id,action,target_type,target_id,details_json,created_at) VALUES(?,?,?,?,?,?)')->execute(array((int)$adminId,'process_commission','referral_commission',(int)$id,json_encode(array('action'=>$action,'success'=>$success,'previous_status'=>$before,'previous_recovery_status'=>$recoveryBefore),JSON_UNESCAPED_UNICODE),date('Y-m-d H:i:s')));
            $this->pdo->commit();return $success;
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    public function referralSummary($userId){
        $s=$this->pdo->prepare('SELECT COUNT(*) FROM referral_relations WHERE referrer_user_id=? AND status="active"');$s->execute(array($userId));$invited=(int)$s->fetchColumn();
        $s=$this->pdo->prepare('SELECT COALESCE(SUM(CASE WHEN settlement_mode="legacy" AND status IN ("available","approved","paid") THEN amount_cents ELSE 0 END),0) earned,COALESCE(SUM(CASE WHEN settlement_mode="wallet" AND status="credited" THEN amount_cents ELSE 0 END),0) wallet_credited,COALESCE(SUM(CASE WHEN settlement_mode="wallet" AND status="pending_credit" THEN amount_cents ELSE 0 END),0) wallet_pending,COALESCE(SUM(CASE WHEN settlement_mode="wallet" AND recovery_status="pending" THEN amount_cents ELSE 0 END),0) wallet_recovery_pending FROM referral_commissions WHERE referrer_user_id=?');$s->execute(array($userId));$totals=$s->fetch();
        $s=$this->pdo->prepare('SELECT COALESCE(SUM(CASE WHEN status IN ("pending","approved","paid") THEN amount_cents ELSE 0 END),0) FROM withdrawal_requests WHERE user_id=?');$s->execute(array($userId));$reserved=(int)$s->fetchColumn();
        return array('invited'=>$invited,'earned'=>(int)$totals['earned'],'available'=>max(0,(int)$totals['earned']-$reserved),'code'=>$this->referralCode($userId),'wallet_credited'=>(int)$totals['wallet_credited'],'wallet_pending'=>(int)$totals['wallet_pending'],'wallet_recovery_pending'=>(int)$totals['wallet_recovery_pending']);
    }
    // 仅聚合展示；除现有活动配置、邀请码初始化外，不发奖、不写入资金。
    public function leaderSummary($userId){
        $userId=(int)$userId;$now=time();$activity=$this->setting('leader');
        $saved=$activity&&!empty($activity['config_json'])?json_decode($activity['config_json'],true):array();
        $cfg=array_merge($this->defaults('leader')['config'],is_array($saved)?$saved:array());
        $required=max(1,(int)$cfg['required_referrals']);$activityState='disabled';
        if($activity&&$activity['status']==='enabled'){
            if(!empty($activity['end_at'])&&strtotime($activity['end_at'])<$now)$activityState='ended';
            elseif(!empty($activity['start_at'])&&strtotime($activity['start_at'])>$now)$activityState='upcoming';
            else $activityState='enabled';
        }
        // 与 tryLeaderReward 完全相同：按好友去重，不额外限定关系、时间或结算模式。
        $s=$this->pdo->prepare('SELECT COUNT(DISTINCT referred_user_id) FROM referral_commissions WHERE referrer_user_id=? AND status IN ("available","approved","paid","pending_credit","credited") AND '.$this->eligibleCommissionSql());
        $s->execute(array($userId));$qualified=(int)$s->fetchColumn();
        $s=$this->pdo->prepare('SELECT COUNT(*) FROM referral_relations WHERE referrer_user_id=? AND status="active"');
        $s->execute(array($userId));$invited=(int)$s->fetchColumn();
        $referralCfg=$this->config('referral');$referralReady=$this->enabled('referral')&&(int)$referralCfg['rate_bps']>0;
        // 当前配置与实际发放套餐分别读取，避免配置变更后误展示历史奖励。
        $plan=null;$rewardPlan=null;
        $planQuery=$this->pdo->prepare('SELECT pp.*,p.name product_name,p.status product_status,p.product_type FROM product_plans pp LEFT JOIN products p ON p.id=pp.product_id WHERE pp.id=?');
        if(!empty($cfg['reward_plan_id'])){
            $planQuery->execute(array((int)$cfg['reward_plan_id']));$plan=$planQuery->fetch()?:null;
        }
        $planAvailable=$plan&&$plan['product_type']==='vpn'&&$plan['status']==='active'&&$plan['product_status']==='active';
        $reward=null;$coupon=null;$couponState='none';$couponOrderNo=null;
        if($activity){
            $s=$this->pdo->prepare('SELECT * FROM leader_rewards WHERE campaign_id=? AND leader_user_id=?');
            $s->execute(array($activity['id'],$userId));$reward=$s->fetch()?:null;
        }
        if($reward){
            $couponState='missing';
            if(!empty($reward['coupon_id'])){
                // 不回退查找其他个人券，且必须属于当前用户。
                $s=$this->pdo->prepare('SELECT * FROM coupons WHERE id=? AND user_id=?');
                $s->execute(array($reward['coupon_id'],$userId));$coupon=$s->fetch()?:null;
            }
        }
        if($coupon){
            // used 表示已被订单占用（可尚未付款），不能据此声称已付款使用。
            if($coupon['status']==='used'||!empty($coupon['used_order_id'])||($coupon['scope']==='personal'&&(int)$coupon['used_quantity']>0))$couponState='used';
            elseif($coupon['status']==='expired'||(!empty($coupon['expires_at'])&&strtotime($coupon['expires_at'])<$now))$couponState='expired';
            elseif($coupon['status']!=='active'||(!empty($coupon['starts_at'])&&strtotime($coupon['starts_at'])>$now)||((int)$coupon['total_quantity']>=0&&(int)$coupon['used_quantity']>=(int)$coupon['total_quantity']))$couponState='inactive';
            else $couponState='available';
            if(!empty($coupon['used_order_id'])){
                $s=$this->pdo->prepare('SELECT order_no FROM orders WHERE id=? AND user_id=?');
                $s->execute(array($coupon['used_order_id'],$userId));$couponOrderNo=$s->fetchColumn()?:null;
            }
            if(!empty($coupon['product_plan_id'])){
                $planQuery->execute(array((int)$coupon['product_plan_id']));$rewardPlan=$planQuery->fetch()?:null;
            }
        }
        return array(
            'activity_state'=>$activityState,'required'=>$required,'qualified'=>$qualified,'invited'=>$invited,
            'remaining'=>max(0,$required-$qualified),'progress'=>min(100,max(0,$qualified/$required*100)),
            'referral_ready'=>$referralReady,'code'=>$this->referralCode($userId),
            'plan'=>$plan,'plan_available'=>(bool)$planAvailable,'reward'=>$reward,'coupon'=>$coupon,
            'coupon_state'=>$couponState,'coupon_order_no'=>$couponOrderNo,'reward_plan'=>$rewardPlan
        );
    }
    public function commissionHistory($userId,$page=1,$perPage=10){
        $perPage=max(1,min(100,(int)$perPage));$s=$this->pdo->prepare('SELECT COUNT(*) FROM referral_commissions WHERE referrer_user_id=?');$s->execute(array((int)$userId));$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=max(1,min($pages,(int)$page));
        $s=$this->pdo->prepare('SELECT c.*,u.email FROM referral_commissions c LEFT JOIN users u ON u.id=c.referred_user_id WHERE c.referrer_user_id=? ORDER BY c.id DESC LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage));$s->execute(array((int)$userId));return array('items'=>$s->fetchAll(),'total'=>$total,'page'=>$page,'pages'=>$pages);
    }
