    public function saveGroupPlans($campaignId,$planIds,$adminId=0){$campaignId=(int)$campaignId;$ids=array();foreach((array)$planIds as $id){$id=(int)$id;if($id>0)$ids[$id]=true;}if(!$ids)throw new InvalidArgumentException('请至少选择一个可拼团套餐方案。');foreach(array_keys($ids) as $id)$this->assertVpnPlan($id);$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT id FROM group_campaigns WHERE id=? FOR UPDATE');$s->execute(array($campaignId));if(!$s->fetch())throw new RuntimeException('拼团活动不存在。');$valid=array();$in=implode(',',array_fill(0,count($ids),'?'));$s=$this->pdo->prepare('SELECT pp.id FROM product_plans pp JOIN products p ON p.id=pp.product_id WHERE pp.id IN ('.$in.') AND pp.status="active" AND p.status="active"');$s->execute(array_keys($ids));foreach($s as $row)$valid[]=(int)$row['id'];if(count($valid)!==count($ids))throw new InvalidArgumentException('包含不存在或已下架的套餐方案。');$this->pdo->prepare('DELETE FROM group_campaign_plans WHERE campaign_id=?')->execute(array($campaignId));$ins=$this->pdo->prepare('INSERT INTO group_campaign_plans(campaign_id,product_plan_id,created_at) VALUES(?,?,?)');$now=date('Y-m-d H:i:s');foreach($valid as $id)$ins->execute(array($campaignId,$id,$now));if($adminId)$this->pdo->prepare('INSERT INTO admin_logs(admin_id,action,target_type,target_id,details_json,created_at) VALUES(?,?,?,?,?,?)')->execute(array($adminId,'update_group_plans','group_campaign',$campaignId,json_encode(array('plan_ids'=>$valid),JSON_UNESCAPED_UNICODE),$now));$this->pdo->commit();}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function prepareGroupPromotion($campaignId,$userId,$planId,$amount){return (new GroupService($this->pdo))->preparePromotion($campaignId,$userId,$planId,$amount);$s=$this->pdo->prepare('SELECT g.*,m.id member_id,m.user_id member_user_id,m.role member_role,m.status member_status,p.product_id FROM group_campaigns g JOIN group_members m ON m.campaign_id=g.id AND m.user_id=? JOIN product_plans p ON p.id=? JOIN group_campaign_plans gp ON gp.campaign_id=g.id AND gp.product_plan_id=p.id WHERE g.id=? AND g.status="forming" AND m.status="pending" AND p.status="active" AND (g.expires_at IS NULL OR g.expires_at>=NOW()) FOR UPDATE');$s->execute(array($userId,(int)$planId,(int)$campaignId));$g=$s->fetch();if(!$g)throw new RuntimeException('拼团成员或套餐方案未被活动允许。');$cfg=$this->config('group');$discount=min($amount,max(0,(int)floor($amount*(100-(int)$cfg['discount_percent'])/100)));return array('discount'=>$discount,'group'=>$g,'promotion_code'=>'group:'.$g['id']);}
    public function attachGroupOrder($orderId,$promotion){return (new GroupService($this->pdo))->attachOrder($orderId,$promotion);$g=$promotion['group'];$now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO group_orders(campaign_id,order_id,user_id,role,status,amount_cents,idempotency_key,created_at,updated_at) VALUES(?,?,?,?,"pending",?,?,?,?)')->execute(array($g['id'],$orderId,$g['member_user_id'],$g['member_role'],(int)$promotion['discount'],'group:'.$orderId,$now,$now));$this->pdo->prepare('UPDATE group_members SET group_order_id=? WHERE id=? AND status="pending"')->execute(array($this->pdo->lastInsertId(),$g['member_id']));}
    public function settleGroupOrder($orderId){throw new LogicException('拼团付款必须由统一订单结算入口执行。');$s=$this->pdo->prepare('SELECT go.*,g.target_members,g.status group_status FROM group_orders go JOIN group_campaigns g ON g.id=go.campaign_id WHERE go.order_id=? FOR UPDATE');$s->execute(array($orderId));$row=$s->fetch();if(!$row||$row['status']!=='pending')return;$s=$this->pdo->prepare('SELECT * FROM group_campaigns WHERE id=? FOR UPDATE');$s->execute(array($row['campaign_id']));$g=$s->fetch();if(!$g||$g['status']!=='forming')return;$now=date('Y-m-d H:i:s');$this->pdo->prepare('UPDATE group_orders SET status="paid",updated_at=? WHERE id=? AND status="pending"')->execute(array($now,$row['id']));$this->pdo->prepare('UPDATE group_members SET status="paid" WHERE group_order_id=? AND status="pending"')->execute(array($row['id']));$count=(int)$g['current_members']+1;$status=$count>=(int)$g['target_members']?'successful':'forming';$this->pdo->prepare('UPDATE group_campaigns SET current_members=?,status=?,updated_at=? WHERE id=?')->execute(array($count,$status,$now,$g['id']));}
    public function reverseGroupOrder($orderId){return (new GroupService($this->pdo))->reverseOrder($orderId);$s=$this->pdo->prepare('SELECT * FROM group_orders WHERE order_id=? FOR UPDATE');$s->execute(array($orderId));$row=$s->fetch();if(!$row||!in_array($row['status'],array('pending','paid'),true))return;$now=date('Y-m-d H:i:s');$this->pdo->prepare('UPDATE group_orders SET status="cancelled",updated_at=? WHERE id=?')->execute(array($now,$row['id']));$this->pdo->prepare('UPDATE group_members SET status="cancelled",left_at=? WHERE group_order_id=?')->execute(array($now,$row['id']));if($row['status']==='paid')$this->pdo->prepare('UPDATE group_campaigns SET current_members=GREATEST(current_members-1,0),status=IF(status="successful","forming",status),updated_at=? WHERE id=?')->execute(array($now,$row['campaign_id']));}
    public function createGroup($userId,$planId){return (new GroupService($this->pdo))->createGroup($userId,$planId);if(!$this->enabled('group'))throw new RuntimeException('好友拼单当前未开启。');$cfg=$this->config('group');$allowed=array_map('intval',isset($cfg['plan_ids'])&&is_array($cfg['plan_ids'])?$cfg['plan_ids']:array());if(!in_array((int)$planId,$allowed,true))throw new RuntimeException('所选套餐方案未开放拼团。');$s=$this->pdo->prepare('SELECT pp.id,pp.product_id,pp.name,pp.status product_plan_status,p.name product_name,p.status product_status FROM product_plans pp JOIN products p ON p.id=pp.product_id WHERE pp.id=? AND pp.status="active" AND p.status="active"');$s->execute(array((int)$planId));$plan=$s->fetch();if(!$plan)throw new RuntimeException('套餐方案不存在或已下架。');$now=date('Y-m-d H:i:s');$expires=date('Y-m-d H:i:s',strtotime('+'.max(1,(int)$cfg['duration_hours']).' hours'));$this->pdo->beginTransaction();try{$this->pdo->prepare('INSERT INTO group_campaigns(campaign_no,creator_user_id,product_id,title,target_members,current_members,member_discount_cents,status,starts_at,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,0,0,"forming",?,?,?,?)')->execute(array($this->code('GP'),$userId,$plan['product_id'],$plan['product_name'].' · 好友拼单',(int)$cfg['target_members'],$now,$expires,$now,$now));$id=$this->pdo->lastInsertId();$campaignPlanIds=array_map('intval',isset($cfg['plan_ids'])&&is_array($cfg['plan_ids'])?$cfg['plan_ids']:array());if(!$campaignPlanIds)throw new RuntimeException('当前没有配置可拼团的套餐方案。');$ins=$this->pdo->prepare('INSERT INTO group_campaign_plans(campaign_id,product_plan_id,created_at) VALUES(?,?,?)');foreach($campaignPlanIds as $campaignPlanId)$ins->execute(array($id,$campaignPlanId,$now));$this->pdo->prepare('INSERT INTO group_members(campaign_id,user_id,role,status,joined_at) VALUES(?, ?,"leader","pending",?)')->execute(array($id,$userId,$now));$this->pdo->commit();return $id;}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function joinGroup($campaignId,$userId,$planId){return (new GroupService($this->pdo))->joinGroup($campaignId,$userId,$planId);$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT * FROM group_campaigns WHERE id=? FOR UPDATE');$s->execute(array((int)$campaignId));$g=$s->fetch();if(!$g||$g['status']!=='forming'||($g['expires_at']&&strtotime($g['expires_at'])<time()))throw new RuntimeException('拼团不存在、已成团或已过期。');$s=$this->pdo->prepare('SELECT 1 FROM group_campaign_plans gp JOIN product_plans pp ON pp.id=gp.product_plan_id JOIN products p ON p.id=pp.product_id WHERE gp.campaign_id=? AND gp.product_plan_id=? AND pp.status="active" AND p.status="active"');$s->execute(array((int)$campaignId,(int)$planId));if(!$s->fetch())throw new RuntimeException('所选套餐方案未被该拼团允许。');$s=$this->pdo->prepare('SELECT id,status FROM group_members WHERE campaign_id=? AND user_id=?');$s->execute(array($campaignId,$userId));$existing=$s->fetch();if($existing){if($existing['status']==='pending'){$this->pdo->commit();return array('status'=>'forming','current_members'=>(int)$g['current_members'],'target_members'=>(int)$g['target_members'],'product_id'=>(int)$g['product_id']);}throw new RuntimeException('你已经加入该拼团。');}$now=date('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO group_members(campaign_id,user_id,role,status,joined_at) VALUES(?, ?,"member","pending",?)')->execute(array($campaignId,$userId,$now));$this->pdo->commit();return array('status'=>'forming','current_members'=>(int)$g['current_members'],'target_members'=>(int)$g['target_members'],'product_id'=>(int)$g['product_id']);}catch(Exception $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
